class A {
  static void ping() { System.out.print("A "); }
  void pong() { System.out.print("a "); }
}
class B extends A {
  static void ping() { System.out.print("B "); }
  @Override void pong() { System.out.print("b "); }
}
public class Demo {
  public static void main(String[] args) {
    A ref = new B();
    ref.ping();
    ref.pong();
  }
}

